{
  "name": "@amykit/plugin-file-notes",
  "version": "0.6.0",
  "description": "Friction as a directory of notes: written by hand, by a hook, or by a tick that failed.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/file-notes"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "@amykit/plugin-notify-fanout": "^0.6.0",
    "@amykit/workflow-note-to-plan": "^0.6.0"
  }
}

import fs from "node:fs";
import path from "node:path";
import { writeNoteFile, type NewNote, type Note, type Notes } from "@amykit/workflow-note-to-plan";

/** The keys the header understands. Anything else is left in the body. */
const REPO = "repo";
const SOURCE = "source";
const WRITTEN = "written";

export interface FileNotesConfig {
  /**
   * What a note is about when it does not say.
   *
   * A note dropped in by hand is usually about the machine that hit the
   * friction, and asking for the repository every time is the kind of
   * ceremony that stops people writing notes at all.
   */
  defaultRepo: string;
}

/**
 * Notes as a directory of markdown files.
 *
 * Markdown with a three-line header rather than JSON, because the whole point
 * of the watched directory is that a note can be written by an editor, by a
 * hook, or by a shell one-liner. A format only a program can produce would
 * have quietly made this a programmatic interface with a directory in front
 * of it.
 *
 * The file name is the id. That makes a note written by hand indistinguishable
 * from one this machine wrote, which is deliberate: both are friction, and
 * neither is more real than the other.
 */
export class FileNotes implements Notes {
  constructor(
    private readonly root: string,
    private readonly config: FileNotesConfig,
  ) {
    fs.mkdirSync(this.root, { recursive: true });
  }

  write(note: NewNote, now: Date): Note {
    return writeNoteFile(this.root, note, now);
  }

  all(): Note[] {
    return fs
      .readdirSync(this.root)
      .filter((name) => name.endsWith(".md"))
      .map((name) => this.read(name.slice(0, -3)))
      .filter((note): note is Note => note !== null)
      .sort((a, b) => a.id.localeCompare(b.id));
  }

  get(id: string): Note | null {
    return this.read(id);
  }

  private read(id: string): Note | null {
    const file = this.file(id);
    if (!fs.existsSync(file)) return null;

    const { header, body } = split(fs.readFileSync(file, "utf-8"));

    return {
      id,
      repo: header[REPO] ?? this.config.defaultRepo,
      text: body.trim(),
      source: header[SOURCE] ?? "somebody at a keyboard",
      // A note written by hand carries no timestamp, and the moment the file
      // appeared is the honest answer rather than the moment it was read.
      writtenAt: header[WRITTEN] ?? fs.statSync(file).mtime.toISOString(),
    };
  }

  /** A sortable id, and a suffix only when two notes land in one millisecond. */
  private file(id: string): string {
    return path.join(this.root, `${id}.md`);
  }
}

/** The header, and everything after it. A file with no header is all body. */
function split(contents: string): { header: Record<string, string>; body: string } {
  const lines = contents.split("\n");
  if (lines[0]?.trim() !== "---") return { header: {}, body: contents };

  const end = lines.indexOf("---", 1);
  if (end === -1) return { header: {}, body: contents };

  const header: Record<string, string> = {};
  for (const line of lines.slice(1, end)) {
    const colon = line.indexOf(":");
    if (colon === -1) continue;
    header[line.slice(0, colon).trim()] = line.slice(colon + 1).trim();
  }

  return { header, body: lines.slice(end + 1).join("\n") };
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  directory: {
    type: "string",
    description: "where the notes are watched for, relative to the state directory",
    default: "notes",
  },
  repo: {
    type: "string",
    default: "",
    description:
      "the repository a note is about when it does not say, which is also the one this machine's own failures are filed against",
  },
  writeFailureNotes: {
    type: "boolean",
    description:
      "whether a tick this machine gave up on leaves a note behind, so the thing that broke becomes the thing that gets fixed",
    default: true,
  },
} satisfies ConfigSchema;

import type { Notes } from "@amykit/workflow-note-to-plan";
import { Channel } from "@amykit/plugin-notify-fanout";

/**
 * Turns the machine giving up into a note about the machine.
 *
 * Only the announcement that says it has stopped, never the one that says it
 * is retrying: a step that failed once and worked on the second attempt is
 * not friction worth a plan, and filing one for it would bury the ones that
 * are. This is why the announcement carries a kind at all.
 *
 * A channel rather than something inside the engine, because it is the same
 * shape as every other way the machine reaches somebody, and because an
 * engine that wrote notes would be an engine that knows what a note is.
 */
export function frictionChannel(notes: Notes, repo: string, now: () => Date): Channel {
  return {
    name: "friction",
    async deliver(announcement) {
      if (announcement.kind !== "gave-up") return;

      notes.write(
        {
          repo,
          source: `a tick that failed in ${announcement.state}`,
          text: [
            announcement.text,
            ``,
            `This came from ${announcement.workId} in ${announcement.state}. What is worth`,
            `writing down is not the one piece of work, it is whatever made the machine`,
            `unable to finish it.`,
          ].join("\n"),
        },
        now(),
      );
    },
  };
}

export { FileNotes } from "./FileNotes.js";
export type { FileNotesConfig } from "./FileNotes.js";
export { frictionChannel } from "./frictionChannel.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import path from "node:path";
import { definePlugin } from "@amykit/core";
import { CHANNEL_COLLECTION } from "@amykit/plugin-notify-fanout";
import { FileNotes } from "./FileNotes.js";
import { configSchema } from "./config.js";
import { frictionChannel } from "./frictionChannel.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-file-notes",
  configSchema,
  register(registry, ctx) {
    const notes = new FileNotes(path.join(ctx.paths.state, ctx.config.directory), {
      defaultRepo: ctx.config.repo,
    });

    registry.port("notes", notes);

    // Mounted in both profiles on purpose. The workflow that reads notes and
    // the workflow whose failures write them are different workflows, and an
    // install that only ran the second would still be filing the friction the
    // first one will pick up.
    // Nothing to file them against means nothing to file, and a channel that
    // wrote notes about the empty repository would be worse than silence.
    if (ctx.config.writeFailureNotes && ctx.config.repo) {
      registry.contribute(
        CHANNEL_COLLECTION,
        "friction",
        frictionChannel(notes, ctx.config.repo, ctx.now),
      );
    }
  },
});
